def ribbon(size=64):
 return f'<svg width="{size}" height="{size}" viewBox="0 0 120 120" aria-hidden="true"><path d="M69 10C107 34 39 80 77 110M43 10C81 34 13 80 51 110" fill="none" stroke="currentColor" stroke-width="12" stroke-linecap="round"/></svg>'

def phone(content, extra=''):
 return f'<div class="phone {extra}"><div class="phone-brand">{ribbon(25)}<span>Sponky</span><span class="sound">◖))</span></div>{content}</div>'

def coach():
 return f'<div class="coach">{ribbon(58)}</div>'

