for s in slides:
 review_cards.append(f'''<section id="{s['slug']}" class="review-frame"><div class="frame-heading"><h2>{s['title']}</h2><span>{s['time']}</span></div><a href="clean/{s['slug']}.png" class="image-link"><img src="clean/{s['slug']}.png" data-slug="{s['slug']}" alt="{s['title']}" width="1920" height="1080"></a><div class="notes"><p><strong>Judging criteria:</strong> {s['criteria']}</p><p><strong>Voice:</strong> {s['caption']}</p><p><strong>Review note:</strong> {s['note']}</p><p><a href="clean/{s['slug']}.png" download>Clean PNG</a> · <a href="captioned/{s['slug']}.png" download>Captioned PNG</a></p></div></section>''')
review_css='''*{box-sizing:border-box}body{margin:0;background:#F7FCF7;color:#004628;font:16px/1.5 Arial,sans-serif}main{max-width:1240px;margin:auto;padding:40px 24px}h1{font-size:36px;line-height:1.1;letter-spacing:-1px;margin:0 0 16px}h2{font-size:22px;line-height:1.25;margin:0}p{margin:8px 0}a{color:#007841}header{margin-bottom:36px}.intro{max-width:850px}.downloads{display:flex;flex-wrap:wrap;gap:20px;margin:20px 0}.toggle{display:inline-flex;align-items:center;gap:10px;min-height:48px}input{width:20px;height:20px}.review-frame{margin:44px 0 60px}.frame-heading{display:flex;justify-content:space-between;align-items:baseline;gap:16px;margin-bottom:16px}.frame-heading>span{white-space:nowrap;color:#666}.image-link{display:block}.image-link img{width:100%;height:auto;display:block;border-radius:12px;border:1px solid #99D59F}.notes{padding:14px 0;color:#363636}.notes strong{color:#004628}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #99D59F}th{width:30%}footer{padding:30px 0;font-size:14px;color:#666}@media(max-width:600px){main{padding:24px 14px}h1{font-size:28px}.frame-heading{display:block}.frame-heading>span{display:block;margin-top:6px}th,td{padding:9px 6px}}'''
review='<header><h1>Sponky · pitch frame review</h1><p class="intro">Eight static 16:9 frames for a 1:55 pitch. Sponky leads the story: notices → explains → checks → guides → celebrates. The user chooses and confirms the goal. The notes below each image are for review only.</p><p class="intro"><strong>UI illustrations are storyboard samples, not captured app screens.</strong> Financial examples use the planned CUST04060 demo figures. Replace or verify each UI scene against the final integrated app before submission.</p><nav class="downloads"><a href="sponky-pitch-deck.pdf">Open clean pitch PDF</a><a href="sponky-pitch-frames.zip" download>Download all frames</a><a href="contact-sheet.png">View contact sheet</a></nav><label class="toggle"><input type="checkbox" id="captions"> Show sample video subtitles</label></header>'
review+='<h2>The five judging criteria · 20% each</h2><table><tbody>'+''.join(f'<tr><th>{c}</th><td>{e}</td></tr>' for c,e in criterion_map)+'</tbody></table>'
review+=''.join(review_cards)
review+='''<footer><p>Sources: <a href="https://github.com/harmittaa/junction_2026/issues/1">S-Pankki challenge and criteria</a> · <a href="https://github.com/harmittaa/junction_2026/issues/44">Current coaching scope</a> · <a href="https://github.com/harmittaa/junction_2026/issues/47">Calculation targets</a> · <a href="https://github.com/harmittaa/junction_2026/issues/50">Integration acceptance</a> · <a href="https://github.com/harmittaa/junction_2026/issues/51">Streak screen</a> · <a href="https://hackjunction.medium.com/how-to-pitch-your-idea-at-a-hackathon-a95cd3f62f60">Junction pitch guidance</a></p><p>Design follows the repository’s Sponky tokens. No claim of live banking, money moved, measured learning gains or measured retention.</p></footer>'''
js="document.getElementById('captions').addEventListener('change',e=>{const folder=e.target.checked?'captioned':'clean';document.querySelectorAll('img[data-slug]').forEach(img=>{const src=folder+'/'+img.dataset.slug+'.png';img.src=src;img.parentElement.href=src;});});"
(ROOT/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sponky pitch review</title><style>'+review_css+'</style></head><body><main>'+review+'</main><script>'+js+'</script></body></html>')
contact=''.join(f'<div><img src="clean/{s["slug"]}.png" width="1920" height="1080"><p>{i:02d} · {s["title"]}</p></div>' for i,s in enumerate(slides,1))
(ROOT/'contact.html').write_text('<!doctype html><html><head><meta charset="utf-8"><title>Sponky frame overview</title><style>body{margin:0;padding:24px;background:#F7FCF7;color:#004628;font:16px Arial}h1{margin:0 0 22px;font-size:30px}main{display:grid;grid-template-columns:1fr 1fr;gap:20px}img{width:100%;height:auto;display:block}p{margin:8px 0 0}</style></head><body><h1>Sponky · the complete pitch</h1><main>'+contact+'</main></body></html>')
